@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100001> ;
            sh:resultMessage "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint _:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <urn:retail:shape:quantity_sign> ;
            sh:value <urn:retail:row:100001> ],
        [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100005> ;
            sh:resultMessage "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint _:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <urn:retail:shape:quantity_sign> ;
            sh:value <urn:retail:row:100005> ],
        [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100006> ;
            sh:resultMessage "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint _:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <urn:retail:shape:quantity_sign> ;
            sh:value <urn:retail:row:100006> ],
        [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100002> ;
            sh:resultMessage "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint _:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <urn:retail:shape:quantity_sign> ;
            sh:value <urn:retail:row:100002> ],
        [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100004> ;
            sh:resultMessage "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint _:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <urn:retail:shape:quantity_sign> ;
            sh:value <urn:retail:row:100004> ],
        [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100008> ;
            sh:resultMessage "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint _:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <urn:retail:shape:quantity_sign> ;
            sh:value <urn:retail:row:100008> ] .

_:ne68498ee17e74d3e81c3e6c45ce3bbb1b2 sh:message "Quantity must be negative for a C-prefix invoice and positive otherwise." ;
    sh:select """
            SELECT $this
            WHERE {
                $this <urn:retail:field:InvoiceNo> ?invoice ;
                      <urn:retail:field:Quantity> ?quantity .
                FILTER (
                    (REGEX(STR(?invoice), "^c", "i") && ?quantity >= 0) ||
                    (!REGEX(STR(?invoice), "^c", "i") && ?quantity <= 0)
                )
            }
        """ .

nonnegative_price.report_turtle:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:100011> ;
            sh:resultMessage "UnitPrice must be greater than or equal to zero." ;
            sh:resultPath <urn:retail:field:UnitPrice> ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinInclusiveConstraintComponent ;
            sh:sourceShape [ sh:message "UnitPrice must be greater than or equal to zero." ;
                    sh:minInclusive 0.0 ;
                    sh:path <urn:retail:field:UnitPrice> ] ;
            sh:value -0.01 ] .
